};

const RoleBuilder = ({ setScreen, addRole }) => {
  const [archetype, setArchetype] = useState(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [draft, setDraft] = useState({ title: '', responsibilities: '', ideal_candidate: '', stipend: '' });
  const [compliance, setCompliance] = useState(0);
  const [lastSaved, setLastSaved] = useState(null);

  useEffect(() => {
    if (draft.title || draft.responsibilities) {
      const timer = setTimeout(() => setLastSaved(new Date()), 1000);
      return () => clearTimeout(timer);
    }
  }, [draft]);

  const handleSelectArchetype = async (type) => {
    setArchetype(type);
    setIsGenerating(true);
    setDraft({ title: `${type} Co-op`, responsibilities: '', ideal_candidate: '', stipend: '' });

    try {
      const res = await callAIWithVS(
        "You are an HR assistant. Draft a compliant, engaging co-op role description based on the selected archetype. Output JSON: { responsibilities, ideal_candidate, suggested_stipend }",
        `Archetype: ${type}. History: Firm usually hires React/Python devs.`
      );
      const data = JSON.parse(res.text.replace(/```json|```/g, ''));

      let currentResp = "";
      const words = data.responsibilities.split(' ');
      for (let i = 0; i < words.length; i++) {
        currentResp += words[i] + " ";
        setDraft(prev => ({ ...prev, responsibilities: currentResp }));
        await new Promise(r => setTimeout(r, 20));
      }
      setDraft(prev => ({ ...prev, ideal_candidate: data.ideal_candidate, stipend: data.suggested_stipend }));
      setCompliance(100);
    } catch (e) {
      setDraft({ title: `${type} Co-op`, responsibilities: "Design, build, and maintain scalable backend services.", ideal_candidate: "Strong problem solver with Python experience.", stipend: 5800 });
      setCompliance(100);
    } finally {
      setIsGenerating(false);
    }
  };

  const handlePublish = () => {
    addRole({
      id: `ROLE-2025S-0${Math.floor(Math.random()*100)}`,
      title: draft.title,
      department: "Engineering",
      status: "Open",
      applicants_count: 0,
      shortlisted_count: 0,
      required_skills: ["Python", "React"],
      policy_checked: true
    });
    setScreen('dashboard');
  };

  return (
    <motion.article className="p-input" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <div>
          <h1 className="display-text">Create Role</h1>
          {lastSaved && <span style={{ fontSize: '0.875rem', color: 'var(--nu-ink-500)' }}>Draft saved at {lastSaved.toLocaleTimeString()}</span>}
        </div>
        <button className="btn-primary" onClick={handlePublish} disabled={compliance < 100}>
          {compliance === 100 ? 'Publish Role' : 'Drafting...'}
        </button>
      </div>

      <div className="grid-2">
        <div className="left-pane">
          <section className="p-pills" style={{ marginBottom: '2rem' }}>
            <h3 style={{ marginBottom: '1rem', fontSize: '1rem' }}>1. Select Archetype to Autofill</h3>
            <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
              {['Software Engineering', 'Data Science', 'Product Management', 'UX Design', 'Marketing'].map(type => (
                <button 
                  key={type} 
                  className={`pill ${archetype === type ? 'active' : ''}`}
                  onClick={() => handleSelectArchetype(type)}
                >
                  {type}
                </button>
              ))}
            </div>
          </section>

          <div className="form-fields">
            <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 500 }}>Role Title</label>
            <input type="text" value={draft.title} onChange={e => setDraft({...draft, title: e.target.value})} placeholder="e.g. Backend Engineering Co-op" />

            <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 500 }}>Responsibilities</label>
            <textarea rows={6} value={draft.responsibilities} onChange={e => setDraft({...draft, responsibilities: e.target.value})} placeholder="Select an archetype to autofill..."></textarea>
          </div>
        </div>

        <div className="right-pane card" style={{ background: '#FAFAFA' }}>
          <section className="p-dial" style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '2rem', paddingBottom: '1rem', borderBottom: '1px solid var(--nu-ink-200)' }}>
            <div className="fit-ring-container" style={{ width: 32, height: 32 }}>
              <svg className="fit-ring-svg" viewBox="0 0 36 36">
                <path className="fit-ring-bg" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
                <path className="fit-ring-fill" strokeDasharray={`${compliance}, 100`} d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
              </svg>
            </div>
            <div>
              <div style={{ fontWeight: 600 }}>Policy Check</div>
              <div style={{ fontSize: '0.875rem', color: compliance === 100 ? 'var(--nu-green)' : 'var(--nu-ink-500)' }}>
                {compliance === 100 ? 'Ready to publish' : 'Awaiting content'}
              </div>
            </div>
          </section>

          <section className="p-synth">
            <h3 style={{ marginBottom: '1rem', fontSize: '1rem', color: 'var(--nu-ink-500)' }}>Live Preview</h3>
            {isGenerating && !draft.responsibilities ? (
              <div className="skeleton" style={{ height: '200px' }}></div>
            ) : (
              <div>
                <h2 style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>{draft.title || 'Role Title'}</h2>
                <p style={{ whiteSpace: 'pre-wrap', marginBottom: '1.5rem' }}>{draft.responsibilities}</p>
                {draft.ideal_candidate && (
                  <>
                    <h4 style={{ marginBottom: '0.5rem' }}>Ideal Candidate</h4>
                    <p style={{ fontSize: '0.875rem', color: 'var(--nu-ink-800)' }}>{draft.ideal_candidate}</p>
                  </>
                )}
                {draft.stipend && (
                  <div style={{ marginTop: '1.5rem', padding: '1rem', background: 'white', borderRadius: '4px', border: '1px solid var(--nu-ink-200)' }}>
                    <strong>Suggested Stipend:</strong> ${draft.stipend}/mo
                  </div>
                )}
              </div>
            )}
          </section>
        </div>
      </div>
    </motion.article>
  );
};

