      --radius-input: 4px;
      --radius-pill: 999px;

      --shadow-soft: 0 4px 12px rgba(11,19,38,0.08);
      --shadow-hover: 0 8px 24px rgba(11,19,38,0.12);
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }
    body {
      font-family: var(--font-body);
      background-color: var(--nu-bg);
      color: var(--nu-ink-900);
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, .display-text {
      font-family: var(--font-display);
      font-weight: 300;
      color: var(--nu-ink-900);
      letter-spacing: -0.01em;
    }
    h1 { font-size: 2.5rem; line-height: 1.1; margin-bottom: 1rem; }
    h2 { font-size: 1.75rem; margin-bottom: 0.75rem; }
    h3 { font-size: 1.25rem; font-weight: 600; }

    .mono-text { font-family: var(--font-mono); font-size: 0.875rem; }

    button {
      font-family: var(--font-body);
      font-weight: 500;
      cursor: pointer;
      border: none;
      transition: all 0.2s ease;
    }

    .btn-primary {
      background: var(--nu-red);
      color: white;
      padding: 0.75rem 1.5rem;
      border-radius: var(--radius-input);
      font-size: 1rem;
    }
    .btn-primary:hover:not(:disabled) { background: var(--nu-red-hover); }
    .btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }
    .btn-primary:active:not(:disabled) { transform: scale(0.98); }

    .btn-secondary {
      background: transparent;
      color: var(--nu-ink-800);
      border: 1px solid var(--nu-ink-200);
      padding: 0.5rem 1rem;
      border-radius: var(--radius-input);
    }
    .btn-secondary:hover { background: var(--nu-ink-200); }

    .card {
      background: var(--nu-surface);
      border-radius: var(--radius-card);
      padding: 1.5rem;
      box-shadow: var(--shadow-soft);
      border: 1px solid var(--nu-ink-200);
    }

    .pill {
      display: inline-flex;
      align-items: center;
      padding: 0.25rem 0.75rem;
      border-radius: var(--radius-pill);
      font-size: 0.875rem;
      background: var(--nu-ink-200);
      color: var(--nu-ink-800);
      border: 1px solid transparent;
    }
    .pill.active {
      background: var(--nu-red-tint);
      color: var(--nu-red);
      border-color: var(--nu-red);
    }

    input[type="text"], textarea, select {
      width: 100%;
      padding: 0.75rem;
      border: 1px solid var(--nu-ink-200);
      border-radius: var(--radius-input);
      font-family: var(--font-body);
      font-size: 1rem;
      margin-bottom: 1rem;
    }
    input:focus, textarea:focus {
      outline: none;
      border-color: var(--nu-red);
      box-shadow: 0 0 0 2px var(--nu-red-tint);
    }

    /* Layouts */
    .app-container { max-width: 1200px; margin: 0 auto; padding: 2rem; }
    .header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 3rem; padding-bottom: 1rem; border-bottom: 1px solid var(--nu-ink-200); }
    .logo-mark { display: flex; align-items: center; gap: 0.75rem; font-family: var(--font-display); font-weight: 600; font-size: 1.25rem; }
    .n-tile { width: 28px; height: 28px; background: var(--nu-red); color: white; display: flex; align-items: center; justify-content: center; font-weight: bold; border-radius: 2px; }

    .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; }
    .grid-3 { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 1.5rem; }

    /* Specific Patterns */
    .p-aspot { margin-bottom: 3rem; }
    .p-kpi { display: flex; gap: 1.5rem; margin-bottom: 2rem; }
    .kpi-card { flex: 1; padding: 1.5rem; background: var(--nu-surface); border-radius: var(--radius-card); border-left: 4px solid var(--nu-ink-800); box-shadow: var(--shadow-soft); }
    .kpi-card .value { font-family: var(--font-display); font-size: 2rem; color: var(--nu-ink-900); }
    .kpi-card .label { color: var(--nu-ink-500); font-size: 0.875rem; text-transform: uppercase; letter-spacing: 0.05em; }

    .p-counterfactual { margin-bottom: 2rem; }
    .alert-card { background: #FFFBEB; border: 1px solid var(--nu-amber); padding: 1.5rem; border-radius: var(--radius-card); display: flex; justify-content: space-between; align-items: center; }

    .p-vignette-trio .candidate-card { 
      background: var(--nu-surface); padding: 1.5rem; border-radius: var(--radius-card); 
      margin-bottom: 1rem; border: 1px solid var(--nu-ink-200); transition: all 0.2s;
      cursor: pointer;
    }
    .p-vignette-trio .candidate-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }
    .p-vignette-trio .candidate-card.selected { border-color: var(--nu-red); background: var(--nu-red-tint); }

    .fit-ring-container { position: relative; width: 48px; height: 48px; }
    .fit-ring-svg { transform: rotate(-90deg); width: 100%; height: 100%; }
    .fit-ring-bg { fill: none; stroke: var(--nu-ink-200); stroke-width: 4; }
    .fit-ring-fill { fill: none; stroke: var(--nu-green); stroke-width: 4; stroke-linecap: round; transition: stroke-dashoffset 1s ease-out; }
    .fit-ring-text { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-family: var(--font-mono); font-size: 0.75rem; font-weight: bold; }

    .skeleton { background: linear-gradient(90deg, var(--nu-ink-200) 25%, #F1F5F9 50%, var(--nu-ink-200) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: 4px; }
    @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }

    .demo-nav { position: fixed; bottom: 16px; right: 16px; z-index: 9999; background: var(--nu-ink-900); padding: 8px; border-radius: 8px; box-shadow: var(--shadow-hover); }
    .demo-nav select { margin: 0; background: transparent; color: white; border: 1px solid rgba(255,255,255,0.2); }
  `}} />
);

