const MatchQueue = ({ role, candidates, setScreen, setSelectedCandidate }) => {
  const [ranked, setRanked] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hoveredId, setHoveredId] = useState(null);
  const [shortlisted, setShortlisted] = useState(new Set());
  const [filterCohort, setFilterCohort] = useState('All');
  const [filterExp, setFilterExp] = useState('All');
  const [detailCandidate, setDetailCandidate] = useState(null);
  const [focusedIndex, setFocusedIndex] = useState(-1);

  useEffect(() => {
    if (!role) return;
    const rankCandidates = async () => {
      setIsLoading(true);
      try {
        await new Promise(r => setTimeout(r, 1200));
        let sorted = [...candidates].sort((a, b) => b.fit_score - a.fit_score);
        if (filterCohort !== 'All') sorted = sorted.filter(c => c.grad_cohort === filterCohort);
        if (filterExp !== 'All') sorted = sorted.filter(c => (filterExp === '1+' ? c.prior_coops_count >= 1 : c.prior_coops_count === 0));

        const withRationales = sorted.slice(0, 8).map(c => ({
          ...c,
          rationale: `Strong overlap in required skills. Prior experience demonstrates capability in ${c.skills[0]} and ${c.skills[1] || 'teamwork'}.`
        }));
        setRanked(withRationales);
      } catch (e) {
        console.error(e);
      } finally {
        setIsLoading(false);
      }
    };
    rankCandidates();
  }, [role, candidates, filterCohort, filterExp]);

  const toggleShortlist = (e, id) => {
    e.stopPropagation();
    const next = new Set(shortlisted);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setShortlisted(next);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setFocusedIndex(prev => Math.min(prev + 1, ranked.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setFocusedIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 's' && focusedIndex >= 0) {
      toggleShortlist({ stopPropagation: () => {} }, ranked[focusedIndex].id);
    } else if (e.key === 'Enter' && focusedIndex >= 0) {
      setDetailCandidate(ranked[focusedIndex]);
    }
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [focusedIndex, ranked, shortlisted]);

  if (!role) return <div>Please select a role from the dashboard.</div>;

  return (
    <motion.article className="p-portfolio-mix" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <header style={{ marginBottom: '2rem' }}>
        <button className="btn-secondary" style={{ marginBottom: '1rem', border: 'none', padding: 0 }} onClick={() => setScreen('dashboard')}>
          <window.lucide.ArrowLeft size={16} style={{ marginRight: '4px', verticalAlign: 'middle' }}/> Back to Dashboard
        </button>
        <h1 className="display-text">Candidate Match Queue</h1>
        <p style={{ fontSize: '1.25rem', color: 'var(--nu-ink-500)' }}>{role.title}</p>
      </header>

      <div style={{ display: 'flex', gap: '1rem', marginBottom: '2rem' }}>
        <select value={filterCohort} onChange={e => setFilterCohort(e.target.value)} style={{ width: 'auto', margin: 0 }} aria-label="Filter by cohort">
          <option value="All">All Cohorts</option>
          <option value="2025">2025</option>
          <option value="2026">2026</option>
          <option value="2027">2027</option>
        </select>
        <select value={filterExp} onChange={e => setFilterExp(e.target.value)} style={{ width: 'auto', margin: 0 }} aria-label="Filter by experience">
          <option value="All">All Experience</option>
          <option value="1+">1+ Prior Co-ops</option>
          <option value="0">First Co-op</option>
        </select>
      </div>

      {isLoading ? (
        <div className="p-vignette-trio">
          {[1,2,3].map(i => (
            <div key={i} className="candidate-card skeleton" style={{ height: '120px' }}></div>
          ))}
        </div>
      ) : (
        <section className="p-vignette-trio">
          {ranked.map((candidate, i) => (
            <motion.div 
              key={candidate.id}
              className={`candidate-card ${focusedIndex === i ? 'focused' : ''}`}
              style={{ border: focusedIndex === i ? '2px solid var(--nu-red)' : '1px solid var(--nu-ink-200)' }}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: i * 0.1 }}
              onMouseEnter={() => setHoveredId(candidate.id)}
              onMouseLeave={() => setHoveredId(null)}
              onClick={() => setDetailCandidate(candidate)}
              tabIndex={0}
              aria-label={`Candidate ${candidate.full_name}, Fit Score ${candidate.fit_score}`}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <h3 style={{ fontSize: '1.25rem', marginBottom: '0.25rem' }}>{candidate.full_name}</h3>
                    {shortlisted.has(candidate.id) && <span className="pill" style={{ background: 'var(--nu-amber)', color: 'white', fontSize: '0.75rem', padding: '2px 6px' }}>Shortlisted</span>}
                  </div>
                  <p className="mono-text" style={{ color: 'var(--nu-ink-500)', marginBottom: '1rem' }}>
                    {candidate.college} • {candidate.major} '{candidate.grad_cohort.slice(-2)}
                  </p>
                  <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                    {candidate.skills.slice(0, 4).map(skill => (
                      <span key={skill} className="pill" style={{ background: 'white', border: '1px solid var(--nu-ink-200)' }}>{skill}</span>
                    ))}
                  </div>
                </div>

                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>
                  <div className="p-dial fit-ring-container" aria-label={`Fit score ${candidate.fit_score} percent`}>
                    <svg className="fit-ring-svg" viewBox="0 0 36 36">
                      <path className="fit-ring-bg" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
                      <motion.path 
                        className="fit-ring-fill" 
                        stroke={candidate.fit_score > 80 ? 'var(--nu-green)' : candidate.fit_score > 60 ? 'var(--nu-amber)' : 'var(--nu-ink-500)'}
                        initial={{ strokeDasharray: "0, 100" }}
                        animate={{ strokeDasharray: `${candidate.fit_score}, 100` }}
                        transition={{ duration: 1, delay: i * 0.1 }}
                        d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" 
                      />
                    </svg>
                    <div className="fit-ring-text">{candidate.fit_score}</div>
                  </div>
                  <button 
                    className="btn-secondary" 
                    style={{ padding: '0.5rem', borderRadius: '50%', border: shortlisted.has(candidate.id) ? '2px solid var(--nu-amber)' : '1px solid var(--nu-ink-200)' }}
                    onClick={(e) => toggleShortlist(e, candidate.id)}
                    aria-label="Shortlist candidate"
                  >
                    <window.lucide.Star size={16} fill={shortlisted.has(candidate.id) ? 'var(--nu-amber)' : 'none'} color={shortlisted.has(candidate.id) ? 'var(--nu-amber)' : 'var(--nu-ink-800)'} />
                  </button>
                </div>
              </div>

              <AnimatePresence>
                {hoveredId === candidate.id && (
                  <motion.div 
                    className="p-trail"
                    initial={{ height: 0, opacity: 0, marginTop: 0 }}
                    animate={{ height: 'auto', opacity: 1, marginTop: '1rem' }}
                    exit={{ height: 0, opacity: 0, marginTop: 0 }}
                    style={{ overflow: 'hidden' }}
                    aria-live="polite"
                  >
                    <div style={{ padding: '1rem', background: 'var(--nu-bg)', borderRadius: '4px', borderLeft: '2px solid var(--nu-red)' }}>
                      <strong style={{ fontSize: '0.75rem', textTransform: 'uppercase', color: 'var(--nu-ink-500)', display: 'block', marginBottom: '0.25rem' }}>AI Rationale</strong>
                      <p style={{ fontSize: '0.875rem' }}>{candidate.rationale}</p>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          ))}
        </section>
      )}

      <AnimatePresence>
        {detailCandidate && (
          <CandidateDetail 
            candidate={detailCandidate} 
            onClose={() => setDetailCandidate(null)} 
            onInterview={(c) => { setSelectedCandidate(c); setScreen('scheduler'); }} 
          />
        )}
      </AnimatePresence>
    </motion.article>
  );
};

const InterviewScheduler = ({ candidate, setScreen }) => {
  const [slots, setSlots] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [confirmed, setConfirmed] = useState(false);

  useEffect(() => {
    const fetchSlots = async () => {
      try {
        const res = await callAIWithFallback(
          "You are a scheduling optimizer. Propose 3 conflict-free interview slots. Output JSON: { slots: [{ datetime, reasoning, is_best_fit }] }",
          "Interviewers: Priya (Free Tue/Thu PM). Student: Amara (Classes Mon/Wed AM). Propose 3 slots."
        );
        const data = JSON.parse(res.text.replace(/```json|```/g, ''));
        setSlots(data.slots || [
          { datetime: "Oct 22, 2:00 PM EST", reasoning: "Avoids student's CS4500 lecture.", is_best_fit: true },
          { datetime: "Oct 23, 10:00 AM EST", reasoning: "Interviewer preferred time.", is_best_fit: false },
          { datetime: "Oct 24, 3:30 PM EST", reasoning: "Mutual open block.", is_best_fit: false }
        ]);
      } catch (e) {
        setSlots([
          { datetime: "Oct 22, 2:00 PM EST", reasoning: "Avoids student's CS4500 lecture.", is_best_fit: true },
          { datetime: "Oct 23, 10:00 AM EST", reasoning: "Interviewer preferred time.", is_best_fit: false }
        ]);
      } finally {
        setIsLoading(false);
      }
    };
    fetchSlots();
  }, []);

  const handleConfirm = () => {
    setConfirmed(true);
    setTimeout(() => setScreen('dashboard'), 1500);
  };

  if (!candidate) return <div>No candidate selected.</div>;

  return (
    <motion.article className="p-sim-pick" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <header style={{ marginBottom: '2rem' }}>
        <h1 className="display-text">Schedule Interview</h1>
        <p style={{ fontSize: '1.25rem', color: 'var(--nu-ink-500)' }}>{candidate.full_name}</p>
      </header>

      <div className="grid-2">
        <div className="card">
          <h3 style={{ marginBottom: '1rem' }}>Interview Details</h3>
          <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 500 }}>Interviewers</label>
          <select defaultValue="Priya Natarajan">
            <option>Priya Natarajan (Engineering)</option>
            <option>David Okafor (Data)</option>
          </select>
          <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 500 }}>Format</label>
          <select defaultValue="Video">
            <option>Video (Zoom)</option>
            <option>In-Person (Boston HQ)</option>
          </select>
        </div>

        <section className="p-synth card">
          <h3 style={{ marginBottom: '1rem' }}>AI Recommended Slots</h3>
          {isLoading ? (
            <div className="skeleton" style={{ height: '200px' }}></div>
          ) : confirmed ? (
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} style={{ textAlign: 'center', padding: '2rem 0' }}>
              <div style={{ width: 48, height: 48, background: 'var(--nu-green)', color: 'white', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem' }}>
                <window.lucide.Check size={24} />
              </div>
              <h4>Interview Scheduled</h4>
              <p style={{ color: 'var(--nu-ink-500)' }}>Invites sent to all parties.</p>
            </motion.div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {slots.map((slot, i) => (
                <motion.div 
                  key={i}
                  style={{ 
                    padding: '1rem', 
                    border: `2px solid ${slot.is_best_fit ? 'var(--nu-red)' : 'var(--nu-ink-200)'}`,
                    borderRadius: 'var(--radius-card)',
                    cursor: 'pointer',
                    background: slot.is_best_fit ? 'var(--nu-red-tint)' : 'white'
                  }}
                  whileHover={{ scale: 1.02 }}
                  onClick={handleConfirm}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                    <strong style={{ fontSize: '1.125rem' }}>{slot.datetime}</strong>
                    {slot.is_best_fit && <span className="pill" style={{ background: 'var(--nu-red)', color: 'white' }}>Best Fit</span>}
                  </div>
                  <p style={{ fontSize: '0.875rem', color: 'var(--nu-ink-800)' }}>{slot.reasoning}</p>
                </motion.div>
              ))}
            </div>
          )}
        </section>
      </div>
    </motion.article>
  );
};

const AnalyticsDashboard = () => {
  const [gaps, setGaps] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        const res = await callAIWithFallback(
          "You are a workforce analytics engine. Identify top 3 skill coverage gaps based on open roles vs applicant pool. Output JSON: { gaps: [{ skill, severity, recommendation }] }",
          "Analyze current cycle data."
        );
        const data = JSON.parse(res.text.replace(/```json|```/g, ''));
        setGaps(data.gaps || []);
      } catch (e) {
        setGaps([
          { skill: "Docker", severity: "high", recommendation: "Relax to 'Preferred' to expand pool by 22%." },
          { skill: "GraphQL", severity: "medium", recommendation: "Consider candidates with strong REST experience." }
        ]);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAnalytics();
  }, []);

  return (
    <motion.article className="p-heat" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <header style={{ marginBottom: '2rem' }}>
        <h1 className="display-text">Funnel Analytics & Coverage</h1>
