                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.25rem' }}>
                    <strong>{gap.skill}</strong>
                    <span className="pill" style={{ background: gap.severity === 'high' ? 'var(--nu-red-tint)' : 'var(--nu-bg)', color: gap.severity === 'high' ? 'var(--nu-red)' : 'inherit' }}>
                      {gap.severity} severity
                    </span>
                  </div>
                  <p style={{ fontSize: '0.875rem', color: 'var(--nu-ink-800)' }}>{gap.recommendation}</p>
