};

const PolicyDrawer = () => {
  const [messages, setMessages] = useState([{ role: 'ai', text: 'Ask me anything about Northeastern Co-op policies.' }]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  const handleSend = async () => {
    if (!input.trim()) return;
    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    try {
      const res = await callAIWithFallback(
        "You are a compliance expert for the Northeastern Co-op program. Answer employer questions accurately. Keep it brief.",
        userMsg
      );
      setMessages(prev => [...prev, { role: 'ai', text: res.text, citation: "Employer Handbook v4, Sec 2.1" }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "I'm having trouble accessing the policy database right now." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <motion.article className="p-chat card" style={{ height: '600px', display: 'flex', flexDirection: 'column' }} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
      <header style={{ borderBottom: '1px solid var(--nu-ink-200)', paddingBottom: '1rem', marginBottom: '1rem' }}>
        <h2 style={{ margin: 0 }}>Policy Assistant</h2>
      </header>

      <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '1rem', paddingRight: '1rem' }}>
        {messages.map((msg, i) => (
          <div key={i} style={{ alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start', maxWidth: '80%' }}>
            <div style={{ 
              padding: '1rem', 
              borderRadius: '8px', 
              background: msg.role === 'user' ? 'var(--nu-ink-900)' : 'var(--nu-bg)',
              color: msg.role === 'user' ? 'white' : 'inherit',
              border: msg.role === 'ai' ? '1px solid var(--nu-ink-200)' : 'none'
            }}>
              {msg.text}
            </div>
            {msg.citation && (
              <div className="p-synth" style={{ fontSize: '0.75rem', color: 'var(--nu-ink-500)', marginTop: '0.5rem', marginLeft: '0.5rem' }}>
                Source: <a href="#" style={{ color: 'var(--nu-red)' }}>{msg.citation}</a>
              </div>
            )}
          </div>
        ))}
        {isTyping && (
          <div className="p-stream" style={{ alignSelf: 'flex-start', padding: '1rem', background: 'var(--nu-bg)', borderRadius: '8px', color: 'var(--nu-ink-500)' }}>
            Assistant is typing...
          </div>
        )}
      </div>

      <div style={{ marginTop: '1rem', display: 'flex', gap: '0.5rem' }}>
        <input 
          type="text" 
          value={input} 
          onChange={e => setInput(e.target.value)} 
          onKeyDown={e => e.key === 'Enter' && handleSend()}
          placeholder="e.g., Can a co-op work 100% remotely?" 
          style={{ margin: 0 }}
        />
        <button className="btn-primary" onClick={handleSend} disabled={isTyping}>
          <window.lucide.Send size={16} />
        </button>
      </div>
    </motion.article>
  );
};

// --- Main App ---
const App = () => {
  const [currentScreen, setCurrentScreen] = useState('dashboard');
  const [roles, setRoles] = useState(SEED_ROLES);
  const [selectedRole, setSelectedRole] = useState(null);
  const [selectedCandidate, setSelectedCandidate] = useState(null);

  const addRole = (role) => setRoles([role, ...roles]);

  return (
    <div className="app-container" data-brand="nu">
      <BrandStyles />
      <Header setScreen={setCurrentScreen} />

      <main>
        <AnimatePresence mode="wait">
          {currentScreen === 'dashboard' && <DashboardHome key="dash" roles={roles} setScreen={setCurrentScreen} setSelectedRole={setSelectedRole} />}
          {currentScreen === 'role_builder' && <RoleBuilder key="build" setScreen={setCurrentScreen} addRole={addRole} />}
          {currentScreen === 'match_queue' && <MatchQueue key="match" role={selectedRole || roles[0]} candidates={SEED_CANDIDATES} setScreen={setCurrentScreen} setSelectedCandidate={setSelectedCandidate} />}
          {currentScreen === 'scheduler' && <InterviewScheduler key="sched" candidate={selectedCandidate || SEED_CANDIDATES[0]} setScreen={setCurrentScreen} />}
          {currentScreen === 'analytics' && <AnalyticsDashboard key="analytics" />}
          {currentScreen === 'policy' && <PolicyDrawer key="policy" />}
        </AnimatePresence>
      </main>

      <div className="demo-nav">
        <select value={currentScreen} onChange={(e) => setCurrentScreen(e.target.value)}>
          <option value="dashboard">Dashboard</option>
          <option value="role_builder">Role Builder</option>
          <option value="match_queue">Match Queue</option>
          <option value="scheduler">Scheduler</option>
          <option value="analytics">Analytics</option>
          <option value="policy">Policy Drawer</option>
        </select>
      </div>
    </div>
  );
};

function __test_state_transitions__() {
  return typeof App === 'function';
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
